### Python

```python
import sys


# 计算单个小朋友可能得到的糖果总数最小值和最大值
def solve_case(n, k, c):
    mn = 0
    mx = 0
    for x in c:
        q = x // k
        r = x % k
        mn += q               # 最少只能拿到下取整
        mx += q + (1 if r > 0 else 0)  # 有余数时，最多可以多拿 1 个
    return mn, mx


def main():
    data = list(map(int, sys.stdin.read().split()))
    t = data[0]
    idx = 1
    ans = []

    for _ in range(t):
        n = data[idx]
        k = data[idx + 1]
        idx += 2
        c = data[idx:idx + n]
        idx += n

        mn, mx = solve_case(n, k, c)
        ans.append(f"{mn} {mx}")

    print("\n".join(ans))


if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {

    // 计算单个小朋友可能得到的糖果总数最小值和最大值
    static long[] solveCase(int n, long k, long[] c) {
        long mn = 0;
        long mx = 0;

        for (int i = 0; i < n; i++) {
            long q = c[i] / k;
            long r = c[i] % k;
            mn += q;                  // 最少只能拿到下取整
            mx += q + (r > 0 ? 1 : 0); // 有余数时，最多可以多拿 1 个
        }

        return new long[]{mn, mx};
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int T = fs.nextInt();
        StringBuilder sb = new StringBuilder();

        while (T-- > 0) {
            int n = fs.nextInt();
            long k = fs.nextLong();
            long[] c = new long[n];

            for (int i = 0; i < n; i++) {
                c[i] = fs.nextLong();
            }

            long[] res = solveCase(n, k, c);
            sb.append(res[0]).append(" ").append(res[1]).append("\n");
        }

        System.out.print(sb.toString());
    }

    // 简单快读，适合本题数据范围
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
